import { sql } from "../lib/db.js";
import { shopifyClientFor } from "../lib/shopify.js";
import type { Request } from "express";
import type {
  InventoryLevelUpdatePayload,
  ProductsDeletePayload,
  OrdersPaidPayload,
  InventoryItemQueryResult,
  NotificationBatchRow,
} from "../types/contracts.js";

// ─── Helper: compute scheduled_send_at respecting quiet hours ────────────────

function computeScheduledSendAt(
  detectedAt: Date,
  quietStart: string,
  quietEnd: string,
  timezone: string,
): Date {
  // Parse HH:MM strings
  const parseHHMM = (hhmm: string): { h: number; m: number } => {
    const [h, m] = hhmm.split(":").map(Number);
    return { h: h ?? 0, m: m ?? 0 };
  };

  // Get current local time components in the given timezone
  const localStr = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(detectedAt);

  // localStr is "HH:MM"
  const [lhStr, lmStr] = localStr.split(":");
  const localH = parseInt(lhStr ?? "0", 10);
  const localM = parseInt(lmStr ?? "0", 10);
  const localMinutes = localH * 60 + localM;

  const startParsed = parseHHMM(quietStart);
  const endParsed = parseHHMM(quietEnd);
  const startMinutes = startParsed.h * 60 + startParsed.m;
  const endMinutes = endParsed.h * 60 + endParsed.m;

  // Determine if we're currently inside quiet hours
  // Handles midnight wrap-around (e.g. 22:00 - 07:00)
  const isQuiet = (mins: number): boolean => {
    if (startMinutes <= endMinutes) {
      // Normal range: e.g. 02:00 - 06:00
      return mins >= startMinutes && mins < endMinutes;
    } else {
      // Wrap-around: e.g. 22:00 - 07:00
      return mins >= startMinutes || mins < endMinutes;
    }
  };

  if (!isQuiet(localMinutes)) {
    // We're in the send window — dispatch immediately
    return detectedAt;
  }

  // We're in quiet hours — schedule for the next quiet-hours end time
  // Build a Date that represents today at quietEnd in the given timezone
  const year = parseInt(
    new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric" }).format(detectedAt),
    10,
  );
  const month = parseInt(
    new Intl.DateTimeFormat("en-CA", { timeZone: timezone, month: "2-digit" }).format(detectedAt),
    10,
  );
  const day = parseInt(
    new Intl.DateTimeFormat("en-CA", { timeZone: timezone, day: "2-digit" }).format(detectedAt),
    10,
  );

  // Construct ISO string for today at quietEnd in UTC
  // Use a simple approach: create the local time string and parse it
  const pad = (n: number): string => String(n).padStart(2, "0");
  const localEndISO = `${year}-${pad(month)}-${pad(day)}T${pad(endParsed.h)}:${pad(endParsed.m)}:00`;

  // Parse the local time as UTC offset using the Intl API trick
  // We compute the UTC offset at the detected time
  const utcDate = new Date(detectedAt);
  const localDateStr = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(utcDate);

  // Parse: "YYYY-MM-DD, HH:MM:SS"
  const parts = localDateStr.replace(",", "").split(/\s+/);
  const datePart = parts[0] ?? "";
  const [lyStr, lmonStr, ldStr] = datePart.split("-");
  const ly = parseInt(lyStr ?? "0", 10);
  const lmon = parseInt(lmonStr ?? "0", 10);
  const ld = parseInt(ldStr ?? "0", 10);

  // Construct "today at endTime" in local timezone as a UTC timestamp
  // by creating a Date from ISO and adjusting for TZ offset
  const localEndDateAsUTC = new Date(`${ly}-${pad(lmon)}-${pad(ld)}T${pad(endParsed.h)}:${pad(endParsed.m)}:00.000Z`);
  // Get UTC offset: parse the same moment back
  const offsetMs = localEndDateAsUTC.getTime() - new Date(localEndISO + "Z").getTime();
  const scheduledLocal = new Date(localEndDateAsUTC.getTime() - offsetMs);

  // If quiet hours wrap midnight (end < start) and end is already past today, advance to tomorrow
  if (scheduledLocal <= detectedAt) {
    scheduledLocal.setUTCDate(scheduledLocal.getUTCDate() + 1);
  }

  return scheduledLocal;
}

// ─── Handler: inventory_levels/update ────────────────────────────────────────

async function handleInventoryLevelUpdate(
  payload: InventoryLevelUpdatePayload,
  _req: Request,
): Promise<void> {
  const inventoryItemId = payload.inventory_item_id;
  const available = payload.available;
  const locationId = payload.location_id;
  const updatedAt = payload.updated_at;

  console.log(
    { topic: "inventory_levels/update", inventoryItemId, locationId, available, updatedAt },
    "received",
  );

  // Only proceed if stock is positive
  if (available === null || available <= 0) {
    console.log({ inventoryItemId, available }, "no positive stock — skipping");
    return;
  }

  // Resolve variant and product from inventory item via Admin GraphQL
  const shopify = await shopifyClientFor();

  const itemData = await shopify.graphql<InventoryItemQueryResult>(
    `query ResolveInventoryItem($id: ID!) {
       inventoryItem(id: $id) {
         id
         variant {
           id
           product {
             id
           }
         }
       }
     }`,
    { id: `gid://shopify/InventoryItem/${inventoryItemId}` },
  );

  if (!itemData.inventoryItem) {
    console.warn({ inventoryItemId }, "inventoryItem not found — skipping");
    return;
  }

  const variantGid = itemData.inventoryItem.variant.id;
  const productGid = itemData.inventoryItem.variant.product.id;

  // Extract numeric IDs from GIDs
  const variantIdStr = variantGid.split("/").pop();
  const productIdStr = productGid.split("/").pop();

  if (!variantIdStr || !productIdStr) {
    console.warn({ variantGid, productGid }, "could not extract numeric ids — skipping");
    return;
  }

  const variantId = BigInt(variantIdStr);
  const productId = BigInt(productIdStr);

  // Check if there are active waitlist entries for this variant or product
  const [entryCount] = await sql<{ count: string }[]>`
    SELECT COUNT(*) AS count
    FROM waitlist_entries
    WHERE (
      (signup_level = 'variant' AND variant_external_id = ${variantId} AND product_external_id = ${productId})
      OR
      (signup_level = 'product' AND product_external_id = ${productId})
    )
    AND status = 'active'
  `;

  const activeCount = parseInt(entryCount?.count ?? "0", 10);
  if (activeCount === 0) {
    console.log({ variantId: variantIdStr, productId: productIdStr }, "no active waitlist entries — skipping");
    return;
  }

  // Idempotency: check if a batch was already created for this item today
  const detectedAt = new Date();
  const todayStart = new Date(detectedAt);
  todayStart.setUTCHours(0, 0, 0, 0);
  const todayEnd = new Date(detectedAt);
  todayEnd.setUTCHours(23, 59, 59, 999);

  const [existingBatch] = await sql<{ id: string; status: string }[]>`
    SELECT id, status
    FROM notification_batches
    WHERE product_external_id = ${productId}
    AND (
      (variant_external_id = ${variantId})
      OR
      (variant_external_id IS NULL AND ${variantId}::bigint IS NULL)
    )
    AND detected_at >= ${todayStart}
    AND detected_at <= ${todayEnd}
    AND status != 'completed'
  `;

  if (existingBatch) {
    console.log(
      { batchId: existingBatch.id, variantId: variantIdStr },
      "batch already exists for today — skipping",
    );
    return;
  }

  // Load quiet hours settings
  const [settings] = await sql<{
    quiet_hours_start: string;
    quiet_hours_end: string;
    timezone: string;
  }[]>`
    SELECT quiet_hours_start, quiet_hours_end, timezone
    FROM notification_settings
    LIMIT 1
  `;

  const quietStart = settings?.quiet_hours_start ?? "22:00";
  const quietEnd = settings?.quiet_hours_end ?? "08:00";
  const timezone = settings?.timezone ?? "America/New_York";

  const scheduledSendAt = computeScheduledSendAt(detectedAt, quietStart, quietEnd, timezone);

  // Create notification batch
  await sql`
    INSERT INTO notification_batches (
      product_external_id,
      variant_external_id,
      available_quantity_at_detection,
      status,
      entries_notified,
      detected_at,
      scheduled_send_at
    ) VALUES (
      ${productId},
      ${variantId},
      ${available},
      'pending',
      0,
      ${detectedAt},
      ${scheduledSendAt}
    )
    ON CONFLICT (product_external_id, variant_external_id, detected_at) DO NOTHING
  `;

  console.log(
    { productId: productIdStr, variantId: variantIdStr, scheduledSendAt },
    "notification batch created",
  );
}

// ─── Handler: products/delete ─────────────────────────────────────────────────

async function handleProductsDelete(
  payload: ProductsDeletePayload,
  _req: Request,
): Promise<void> {
  const productId = BigInt(payload.id);

  console.log({ topic: "products/delete", productId: String(productId) }, "received");

  await sql.begin(async (tx) => {
    // Cancel pending batches for this product
    await tx`
      UPDATE notification_batches
      SET status = 'completed',
          completed_at = now()
      WHERE product_external_id = ${productId}
      AND status = 'pending'
    `;

    // Cascade-delete waitlist entries (conversions cascade from entries via FK)
    await tx`
      DELETE FROM waitlist_entries
      WHERE product_external_id = ${productId}
    `;

    // Clean up dashboard snapshots
    await tx`
      DELETE FROM dashboard_snapshots
      WHERE product_external_id = ${productId}
    `;
  });

  console.log({ productId: String(productId) }, "waitlist cascade-deleted");
}

// ─── Handler: orders/paid ─────────────────────────────────────────────────────

async function handleOrdersPaid(
  payload: OrdersPaidPayload,
  _req: Request,
): Promise<void> {
  const orderId = BigInt(payload.id);
  const buyerEmail = payload.email;
  const processedAt = new Date(payload.processed_at);
  const lineItems = payload.line_items;

  console.log({ topic: "orders/paid", orderId: String(orderId), buyerEmail }, "received");

  // Idempotency: skip if we've already processed this order
  const [existing] = await sql<{ id: string }[]>`
    SELECT id FROM conversions
    WHERE order_external_id = ${orderId}
    LIMIT 1
  `;

  if (existing) {
    console.log({ orderId: String(orderId) }, "conversion already recorded — skipping");
    return;
  }

  // Collect variant ids from line items (filter nulls)
  const variantIds = lineItems
    .map((li) => li.variant_id)
    .filter((id): id is number => id !== null && id !== undefined)
    .map((id) => BigInt(id));

  if (variantIds.length === 0) {
    console.log({ orderId: String(orderId) }, "no variant ids in order — skipping");
    return;
  }

  // Attribution window: 7 days
  const attributionWindowMs = 7 * 24 * 60 * 60 * 1000;
  const windowStart = new Date(processedAt.getTime() - attributionWindowMs);

  // Find notified waitlist entries for this buyer within the attribution window
  const notifiedEntries = await sql<{
    id: string;
    product_external_id: bigint;
    variant_external_id: bigint | null;
    notified_at: Date;
  }[]>`
    SELECT id, product_external_id, variant_external_id, notified_at
    FROM waitlist_entries
    WHERE shopper_email = ${buyerEmail}
    AND status IN ('notified', 'converted')
    AND notified_at IS NOT NULL
    AND notified_at >= ${windowStart}
    AND notified_at <= ${processedAt}
  `;

  if (notifiedEntries.length === 0) {
    console.log({ orderId: String(orderId), buyerEmail }, "no notified entries in window — skipping");
    return;
  }

  // Match each notified entry against purchased variant ids
  const variantIdStrings = new Set(variantIds.map((v) => String(v)));

  for (const entry of notifiedEntries) {
    const entryVariantStr = entry.variant_external_id !== null
      ? String(entry.variant_external_id)
      : null;

    // Match: variant-level entry matches if variant was purchased
    // Product-level entry matches if any variant of the product was purchased
    const isMatch = entryVariantStr !== null
      ? variantIdStrings.has(entryVariantStr)
      : variantIds.some((_v) => {
          // For product-level entries, we match any purchase — we trust the entry product_external_id
          // matches the product (set at signup). A product-level entry matches any line item.
          return true;
        });

    if (!isMatch) continue;

    // Record conversion (idempotent via ON CONFLICT)
    await sql`
      INSERT INTO conversions (
        waitlist_entry_id,
        order_external_id,
        shopper_email,
        product_external_id,
        variant_external_id,
        notified_at,
        converted_at
      ) VALUES (
        ${entry.id},
        ${orderId},
        ${buyerEmail},
        ${entry.product_external_id},
        ${entry.variant_external_id},
        ${entry.notified_at!},
        ${processedAt}
      )
      ON CONFLICT (order_external_id, waitlist_entry_id) DO NOTHING
    `;

    // Update waitlist entry status to converted
    await sql`
      UPDATE waitlist_entries
      SET status = 'converted'
      WHERE id = ${entry.id}
      AND status = 'notified'
    `;
  }

  console.log({ orderId: String(orderId), buyerEmail }, "conversion processing complete");
}

// ─── Export ───────────────────────────────────────────────────────────────────

export const webhookHandlers = {
  "inventory_levels/update": async (payload: InventoryLevelUpdatePayload, req: Request) => {
    await handleInventoryLevelUpdate(payload, req);
  },
  "products/delete": async (payload: ProductsDeletePayload, req: Request) => {
    await handleProductsDelete(payload, req);
  },
  "orders/paid": async (payload: OrdersPaidPayload, req: Request) => {
    await handleOrdersPaid(payload, req);
  },
};
